select id, tenant_id, area_code, area_name, parent_id, area_type, site_id, risk_level, major_hazard_flag, sort_no, status, created_at, updated_at, deleted from base_area where tenant_id = #{tenantId} and deleted = 0
and (area_code like concat('%', #{keyword}, '%') or area_name like concat('%', #{keyword}, '%'))
and status = #{status}
order by id desc limit #{limit} offset #{offset}

select count(1) from base_area where tenant_id = #{tenantId} and deleted = 0
and (area_code like concat('%', #{keyword}, '%') or area_name like concat('%', #{keyword}, '%'))
and status = #{status}
